            rate = None
            uncertainty = None
            score = None
        summaries.append(
            {
                "scenario": scenario,
                "count": count,
                "moves": moves,
                "coverage": coverage,
                "agreement": agreement,
                "rate": rate,
                "uncertainty": uncertainty,
                "score": score,
            }
        )

    ranked = sorted(
        (summary for summary in summaries if summary["score"] is not None),
        key=lambda summary: summary["score"],
        reverse=True,
    )
    ordered = [None] * len(summaries)
    position = 0
    for rank, summary in enumerate(ranked, start=1):
